    private const string ExampleInput = ".......S.......\n...............\n.......^.......\n...............\n......^.^......\n...............\n.....^.^.^.....\n...............\n....^.^...^....\n...............\n...^.^...^.^...\n...............\n..^...^.....^..\n...............\n.^.^.^.^.^...^.\n...............";

    private int m_result;

    public int GetResultPartOne()
    {
        char[][] rows = MyInput.Split('\n').Select(s => s.ToCharArray()).ToArray();;

        List<int> indexOfBeams = [rows[0].IndexOf('S')];

        for (int i = 1; i < rows.Length; i++)
        {
            char[] currentRow = rows[i];
            List<int> newIndexOfBeams = [];
            
            foreach (int indexOfBeam in indexOfBeams)
            {
                if (currentRow[indexOfBeam] == '^')
                {
                    newIndexOfBeams.Add(indexOfBeam + 1);
                    newIndexOfBeams.Add(indexOfBeam - 1);
                    m_result++;
                }
                else
                {
                    newIndexOfBeams.Add(indexOfBeam);
                }
            }

            indexOfBeams = newIndexOfBeams;
        }
        return m_result;
    }
    
    public long GetResultPartTwo()
    {
        char[][] rows = MyInput.Split('\n').Select(s => s.ToCharArray()).ToArray();;

        long[,] cachedResults = new long[rows.Length, rows[0].Length];

        int indexOfBeam = rows[0].IndexOf('S');
        
        return GoNextStep(rows, cachedResults, 1, indexOfBeam);
    }

    public static long GoNextStep(char[][] matrix, long[,] cachedResults, int currentRow, int indexOfBeam)
    {
        if (currentRow == matrix.Length - 1) return 1;

        int nextRow = currentRow + 1;

        if (cachedResults[currentRow, indexOfBeam] != 0) return cachedResults[currentRow, indexOfBeam];
        
        if (matrix[currentRow][indexOfBeam] == '^')
        {
            long right = GoNextStep(matrix, cachedResults, nextRow, indexOfBeam + 1);
            long left = GoNextStep(matrix, cachedResults, nextRow, indexOfBeam - 1);
            
            cachedResults[currentRow, indexOfBeam] = right + left;
            return right + left;
        }

        return GoNextStep(matrix, cachedResults, nextRow, indexOfBeam);
    }
